window.AZ_GRAMMAR_ETS=[{"t": 1, "n": 102, "topic": "tu-loai", "q": "The ------- antique shop in Pepper Valley will close down next month.", "choices": ["last", "lasts", "lasted", "lasting"], "correct": 0, "explain": "Dịch: Cửa hàng đồ cổ cuối cùng ở Pepper Valley sẽ đóng cửa tháng sau. — Giữa \"The\" và danh từ \"antique shop\" cần tính từ: \"last\" (cuối cùng còn lại). \"lasting\" (bền lâu) sai nghĩa.", "src": "ETS 2026 · Test 1 · Câu 102"}, {"t": 1, "n": 110, "topic": "tu-loai", "q": "The cash registers at Pirkle Books automatically ------- the remaining inventory of books available.", "choices": ["calculate", "calculator", "calculating", "calculation"], "correct": 0, "explain": "Dịch: Máy tính tiền ở Pirkle Books tự động tính số sách còn tồn kho. — Câu thiếu động từ chính sau chủ ngữ số nhiều \"The cash registers\" (trạng từ automatically đứng trước) → \"calculate\".", "src": "ETS 2026 · Test 1 · Câu 110"}, {"t": 1, "n": 112, "topic": "tu-loai", "q": "According to CEO Mayu Yamada, it would not be ------- responsible to expand the warehouse at this time.", "choices": ["finance", "financials", "financially", "financing"], "correct": 2, "explain": "Dịch: Theo CEO, mở rộng kho lúc này sẽ không hợp lý về mặt tài chính. — Trước tính từ \"responsible\" cần trạng từ bổ nghĩa → \"financially\".", "src": "ETS 2026 · Test 1 · Câu 112"}, {"t": 1, "n": 116, "topic": "tu-loai", "q": "Theta Industries' training program aims to increase the ------- of its manufacturing systems.", "choices": ["producer", "produced", "productive", "productivity"], "correct": 3, "explain": "Dịch: Chương trình đào tạo nhằm tăng năng suất của hệ thống sản xuất. — Sau \"the\" và trước \"of\" cần danh từ; nghĩa \"năng suất\" → \"productivity\". \"producer\" (nhà sản xuất) sai nghĩa.", "src": "ETS 2026 · Test 1 · Câu 116"}, {"t": 1, "n": 124, "topic": "tu-loai", "q": "The City of Doyle's new downtown parking ------- have been met with opposition by residents and visitors.", "choices": ["restricts", "restricted", "restrictions", "restricting"], "correct": 2, "explain": "Dịch: Các quy định hạn chế đỗ xe mới ở trung tâm bị cư dân phản đối. — Danh từ ghép \"parking ___\" làm chủ ngữ, động từ \"have been\" số nhiều → danh từ số nhiều \"restrictions\".", "src": "ETS 2026 · Test 1 · Câu 124"}, {"t": 1, "n": 126, "topic": "tu-loai", "q": "With its fixed price -------, Omega Cellular guarantees no phone bill increases for three years.", "choices": ["assurance", "assuredly", "assuring", "assures"], "correct": 0, "explain": "Dịch: Với cam kết giá cố định, Omega Cellular bảo đảm không tăng cước ba năm. — \"its fixed price ___\" cần danh từ làm trung tâm cụm → \"assurance\".", "src": "ETS 2026 · Test 1 · Câu 126"}, {"t": 1, "n": 130, "topic": "tu-loai", "q": "For a $95 ------- fee, our mechanics will determine what repairs are needed.", "choices": ["diagnosed", "diagnostic", "diagnosable", "diagnose"], "correct": 1, "explain": "Dịch: Với phí chẩn đoán 95 đô, thợ sẽ xác định cần sửa gì. — Giữa \"$95\" và danh từ \"fee\" cần tính từ → \"diagnostic\".", "src": "ETS 2026 · Test 1 · Câu 130"}, {"t": 1, "n": 143, "topic": "tu-loai", "title": "E-mail", "passage": "Dear Ms. Zalen,\n\nThank you for your recent visit to Kaymar Primary Care Practice. We hope you found our services {{Q}}, and we welcome suggestions for improvement.\n\nWe have posted a summary of your consultation on our portal. Please take a moment to go through it and let us know if you have any questions.", "q": "Chọn đáp án điền vào chỗ trống (143) trong đoạn văn.", "choices": ["satisfied", "satisfaction", "satisfactory", "satisfactorily"], "correct": 2, "explain": "Dịch: Chúng tôi mong bạn thấy dịch vụ của chúng tôi đạt yêu cầu. — Cấu trúc \"find + O + tính từ\": find our services satisfactory. \"satisfied\" dùng cho người cảm thấy hài lòng, không cho dịch vụ.", "src": "ETS 2026 · Test 1 · Câu 143"}, {"t": 2, "n": 102, "topic": "tu-loai", "q": "The staff was grateful for the ------- that Mr. Schuller distributed at the meeting.", "choices": ["information", "informed", "informs", "inform"], "correct": 0, "explain": "Dịch: Nhân viên biết ơn những thông tin ông Schuller phát trong buổi họp. — Sau \"the\" cần danh từ → \"information\" (không đếm được).", "src": "ETS 2026 · Test 2 · Câu 102"}, {"t": 2, "n": 108, "topic": "tu-loai", "q": "The Southport ------- plant is expected to begin production in three days.", "choices": ["manufacture", "manufactured", "manufacturing", "manufactures"], "correct": 2, "explain": "Dịch: Nhà máy sản xuất ở Southport dự kiến hoạt động sau ba ngày. — Danh từ ghép \"manufacturing plant\" (nhà máy sản xuất): V-ing làm định ngữ chỉ chức năng.", "src": "ETS 2026 · Test 2 · Câu 108"}, {"t": 2, "n": 112, "topic": "tu-loai", "q": "During Mr. Nagahori's tenure as CEO at Unten Properties, the company has grown -------.", "choices": ["signify", "significance", "significant", "significantly"], "correct": 3, "explain": "Dịch: Trong nhiệm kỳ của ông Nagahori, công ty đã tăng trưởng đáng kể. — Bổ nghĩa cho động từ \"has grown\" → trạng từ \"significantly\".", "src": "ETS 2026 · Test 2 · Câu 112"}, {"t": 2, "n": 116, "topic": "tu-loai", "q": "Because of an abundance of ------- candidates, Xaniper Industries may take longer than expected to name a new CEO.", "choices": ["qualify", "qualifier", "qualified", "qualifies"], "correct": 2, "explain": "Dịch: Vì có quá nhiều ứng viên đủ năng lực, Xaniper có thể mất lâu hơn để chọn CEO. — Trước danh từ \"candidates\" cần tính từ → \"qualified\" (đủ năng lực).", "src": "ETS 2026 · Test 2 · Câu 116"}, {"t": 2, "n": 122, "topic": "tu-loai", "q": "At Blu Hedge, clients receive 1 percent interest, pay no account fees, and can make unlimited -------.", "choices": ["transfer", "transfers", "transferred", "transferring"], "correct": 1, "explain": "Dịch: Khách hàng có thể chuyển khoản không giới hạn số lần. — Sau tính từ \"unlimited\" cần danh từ; \"transfer\" đếm được, không có mạo từ → số nhiều \"transfers\".", "src": "ETS 2026 · Test 2 · Câu 122"}, {"t": 2, "n": 134, "topic": "tu-loai", "title": "Advertisement", "passage": "One day nearly 160 years ago, Arianna Sweeney brought some of her homemade muffins to the local town square to give to her friends. Everyone loved them! Before long, Ms. Sweeney started sharing muffins with anyone who wanted one. [ … ]. After a few months, she became known around town as the Muffin Lady.\n\nToday, Muffin Lady Muffins are made by hand using the same original recipes developed by Arianna Sweeney. We are committed to baking Muffin Lady Muffins authentically with only the finest ingredients. We hope you enjoy our delicious {{Q}}!", "q": "Chọn đáp án điền vào chỗ trống (134) trong đoạn văn.", "choices": ["creates", "created", "creatively", "creations"], "correct": 3, "explain": "Dịch: Mong bạn thưởng thức những sản phẩm thơm ngon của chúng tôi. — Sau \"our delicious\" cần danh từ → \"creations\".", "src": "ETS 2026 · Test 2 · Câu 134"}, {"t": 2, "n": 135, "topic": "tu-loai", "title": "Product description", "passage": "Teksheen Supply >> Products >> Natural Hand Soap\n\nMany brands of hand soap contain unnecessary chemicals. For those who {{Q}} a soap with no added artificial substances, Teksheen Supply's natural hand soap is the ideal choice. This unscented soap is packaged in a handy dispenser bottle. Its patented formula is designed to keep your hands clean yet soft with a mix of natural vitamins and oils. [ … ]. Do you operate a business and want a safe and effective hand soap manufactured through sustainable processes? If so, you may purchase this item in bulk at discounted prices. Visit our Ordering page for details.", "q": "Chọn đáp án điền vào chỗ trống (135) trong đoạn văn.", "choices": ["prefer", "preferring", "preferable", "preference"], "correct": 0, "explain": "Dịch: Với những ai thích xà phòng không có chất nhân tạo, xà phòng tự nhiên của Teksheen là lựa chọn lý tưởng. — Mệnh đề quan hệ \"who ___ a soap\" thiếu động từ chính, \"those\" số nhiều → \"prefer\".", "src": "ETS 2026 · Test 2 · Câu 135"}, {"t": 3, "n": 103, "topic": "tu-loai", "q": "A full-scale ------- will be conducted by the accounting department.", "choices": ["reviewer", "review", "reviewed", "reviews"], "correct": 1, "explain": "Dịch: Phòng kế toán sẽ tiến hành một cuộc rà soát toàn diện. — Sau \"A full-scale\" cần danh từ số ít → \"review\" (\"reviewer\" là người, sai nghĩa).", "src": "ETS 2026 · Test 3 · Câu 103"}, {"t": 3, "n": 105, "topic": "tu-loai", "q": "The report found that employees who take regular breaks are more ------- than those who take no breaks.", "choices": ["production", "productively", "productivity", "productive"], "correct": 3, "explain": "Dịch: Nhân viên nghỉ giải lao đều đặn làm việc hiệu quả hơn người không nghỉ. — Sau \"be + more\" cần tính từ (so sánh hơn) → \"productive\".", "src": "ETS 2026 · Test 3 · Câu 105"}, {"t": 3, "n": 111, "topic": "tu-loai", "q": "A majority of the city's residents rated its transportation app as -------.", "choices": ["acceptability", "acceptable", "acceptance", "accepting"], "correct": 1, "explain": "Dịch: Phần lớn cư dân đánh giá ứng dụng giao thông là chấp nhận được. — \"rate + O + as + tính từ\" → \"acceptable\".", "src": "ETS 2026 · Test 3 · Câu 111"}, {"t": 3, "n": 114, "topic": "tu-loai", "q": "Because it submitted the lowest bid, Deb's Gifting has been chosen as the ------- of this year's holiday cards.", "choices": ["supply", "supplier", "supplies", "supplying"], "correct": 1, "explain": "Dịch: Vì bỏ thầu thấp nhất, Deb's Gifting được chọn làm nhà cung cấp thiệp năm nay. — Sau \"the\" cần danh từ chỉ người/đơn vị → \"supplier\".", "src": "ETS 2026 · Test 3 · Câu 114"}, {"t": 3, "n": 121, "topic": "tu-loai", "q": "Ms. Yamada, ------- director of the Midlands Chamber of Commerce, was recently appointed to the state trade commission.", "choices": ["formed", "former", "formalize", "formality"], "correct": 1, "explain": "Dịch: Bà Yamada, cựu giám đốc Phòng Thương mại Midlands, vừa được bổ nhiệm… — Trước danh từ \"director\" cần tính từ → \"former\" (cựu, trước đây).", "src": "ETS 2026 · Test 3 · Câu 121"}, {"t": 3, "n": 127, "topic": "tu-loai", "q": "Opal City's Community Theater is holding ------- for its spring production during the first week of December.", "choices": ["to audition", "auditioned", "auditions", "audition"], "correct": 2, "explain": "Dịch: Nhà hát cộng đồng đang tổ chức các buổi thử vai cho vở mùa xuân. — Sau động từ \"is holding\" cần tân ngữ là danh từ; không có mạo từ → số nhiều \"auditions\".", "src": "ETS 2026 · Test 3 · Câu 127"}, {"t": 3, "n": 131, "topic": "tu-loai", "title": "Bank advertisement", "passage": "Take advantage of double rewards for a limited time!\n\nStretch your holiday season's shopping spree into January, and we will reward you with $4 cash back on every {{Q}} of $50 or more. Additionally, cashback rewards will be automatically deposited into a separate Avanti savings account and earn a 3% annual interest rate. Enroll in our double-rewards program on Avanti's mobile or desktop app. Alternatively, stop by an Avanti branch for assistance. [ … ]. On February 1, cashback rewards will return to $2 per $50 transaction.", "q": "Chọn đáp án điền vào chỗ trống (131) trong đoạn văn.", "choices": ["purchase", "purchaser", "purchased", "purchasing"], "correct": 0, "explain": "Dịch: Chúng tôi hoàn 4 đô cho mỗi giao dịch mua từ 50 đô trở lên. — Sau \"every\" cần danh từ số ít → \"purchase\".", "src": "ETS 2026 · Test 3 · Câu 131"}, {"t": 3, "n": 132, "topic": "tu-loai", "title": "Bank advertisement", "passage": "Take advantage of double rewards for a limited time!\n\nStretch your holiday season's shopping spree into January, and we will reward you with $4 cash back on every purchase of $50 or more. Additionally, cashback rewards will be {{Q}} deposited into a separate Avanti savings account and earn a 3% annual interest rate. Enroll in our double-rewards program on Avanti's mobile or desktop app. Alternatively, stop by an Avanti branch for assistance. [ … ]. On February 1, cashback rewards will return to $2 per $50 transaction.", "q": "Chọn đáp án điền vào chỗ trống (132) trong đoạn văn.", "choices": ["automate", "automatic", "automation", "automatically"], "correct": 3, "explain": "Dịch: Tiền hoàn sẽ được tự động chuyển vào một tài khoản tiết kiệm riêng. — Giữa \"will be\" và V3 \"deposited\" cần trạng từ → \"automatically\".", "src": "ETS 2026 · Test 3 · Câu 132"}, {"t": 3, "n": 137, "topic": "tu-loai", "title": "E-mail", "passage": "I am excited to share the news that Winnie Liu, our longtime team captain, will be moving on. Fortunately, she will not be leaving the company. Instead, Winnie will serve as our new regional distribution manager. We are thrilled about her promotion.\n\nWe would like to show our appreciation for everything Winnie has done for our department, especially for our team. We will be hosting a party for Winnie in the break room at 3:00 P.M. on February 28, her {{Q}} day with us. [ … ]. We look forward to seeing you there.\n\nBest,", "q": "Chọn đáp án điền vào chỗ trống (137) trong đoạn văn.", "choices": ["final", "finalize", "finalized", "finally"], "correct": 0, "explain": "Dịch: Tiệc chia tay vào ngày 28/2, ngày làm việc cuối cùng của Winnie. — Giữa \"her\" và danh từ \"day\" cần tính từ → \"final\".", "src": "ETS 2026 · Test 3 · Câu 137"}, {"t": 4, "n": 105, "topic": "tu-loai", "q": "We hope our customer service team has answered your questions in a ------- manner.", "choices": ["satisfy", "satisfactory", "satisfaction", "satisfactorily"], "correct": 1, "explain": "Dịch: Mong đội chăm sóc khách hàng đã trả lời câu hỏi của bạn một cách thoả đáng. — \"in a ___ manner\": giữa \"a\" và danh từ \"manner\" cần tính từ → \"satisfactory\".", "src": "ETS 2026 · Test 4 · Câu 105"}, {"t": 4, "n": 109, "topic": "tu-loai", "q": "Mr. Aziz is often alone in the shop while his partner is out making a -------.", "choices": ["deliver", "delivery", "delivered", "delivering"], "correct": 1, "explain": "Dịch: Ông Aziz thường ở một mình trong tiệm khi cộng sự đi giao hàng. — Sau \"a\" cần danh từ; \"make a delivery\" là cụm cố định.", "src": "ETS 2026 · Test 4 · Câu 109"}, {"t": 4, "n": 119, "topic": "tu-loai", "q": "The Terry Hoig Prize for ------- architecture was awarded to Ms. Helblon on Tuesday.", "choices": ["sustain", "sustainable", "sustainer", "sustains"], "correct": 1, "explain": "Dịch: Giải Terry Hoig cho kiến trúc bền vững được trao cho bà Helblon. — Trước danh từ \"architecture\" cần tính từ → \"sustainable\".", "src": "ETS 2026 · Test 4 · Câu 119"}, {"t": 4, "n": 121, "topic": "tu-loai", "q": "Two students from Wrisley University worked ------- on the design of the new library in Lorth Park.", "choices": ["collaborate", "collaborative", "collaboratively", "collaborated"], "correct": 2, "explain": "Dịch: Hai sinh viên đã cộng tác cùng nhau thiết kế thư viện mới. — Bổ nghĩa cho động từ \"worked\" → trạng từ \"collaboratively\".", "src": "ETS 2026 · Test 4 · Câu 121"}, {"t": 4, "n": 123, "topic": "tu-loai", "q": "At Beautyvale Cosmetics, our representatives answer customers' ------- within 24 hours of receipt.", "choices": ["inquirers", "inquired", "to inquire", "inquiries"], "correct": 3, "explain": "Dịch: Nhân viên trả lời thắc mắc của khách trong vòng 24 giờ. — Sau sở hữu cách \"customers'\" cần danh từ; nghĩa \"thắc mắc\" → \"inquiries\" (\"inquirers\" là người hỏi).", "src": "ETS 2026 · Test 4 · Câu 123"}, {"t": 4, "n": 127, "topic": "tu-loai", "q": "The accounting department's new policy outlines the ------- process for the procurement of office equipment.", "choices": ["preferring", "preferably", "preferred", "preferability"], "correct": 2, "explain": "Dịch: Chính sách mới nêu quy trình được ưu tiên áp dụng cho việc mua thiết bị. — Trước danh từ \"process\" cần tính từ → \"preferred\" (được ưu tiên).", "src": "ETS 2026 · Test 4 · Câu 127"}, {"t": 4, "n": 129, "topic": "tu-loai", "q": "Granta Hospital has added several pediatric nurses to its staff as part of its new ------- with the Friel School of Nursing.", "choices": ["affiliation", "affiliated", "affiliating", "affiliates"], "correct": 0, "explain": "Dịch: Bệnh viện Granta tuyển thêm y tá nhi trong khuôn khổ liên kết mới với trường Điều dưỡng Friel. — Sau \"its new\" cần danh từ số ít → \"affiliation\".", "src": "ETS 2026 · Test 4 · Câu 129"}, {"t": 4, "n": 135, "topic": "tu-loai", "title": "Notice", "passage": "Connelly's Parking Garage\n\nParking is $10 per hour unless you get your parking validated at a {{Q}} store. Stores that can validate your parking include Raymond's Department Store, Lola's Fine Dining, Monique's Boutique, and Gretsch Chocolatiers. Just bring your entrance ticket to any of these establishments. [ … ]. You will get your first hour of parking at no charge. Then, the fee will be $5 per hour.", "q": "Chọn đáp án điền vào chỗ trống (135) trong đoạn văn.", "choices": ["participates", "participated", "participating", "participation"], "correct": 2, "explain": "Dịch: Gửi xe 10 đô/giờ trừ khi bạn có xác nhận tại một cửa hàng tham gia chương trình. — Trước danh từ \"store\" cần tính từ; V-ing mang nghĩa chủ động \"cửa hàng tham gia\" → \"participating\".", "src": "ETS 2026 · Test 4 · Câu 135"}, {"t": 4, "n": 141, "topic": "tu-loai", "title": "Announcement", "passage": "Lost Ocean Theater is thrilled to announce a unique offering coming to its downtown location next week. The talented comedian Maddy Chang will perform a one-person show based on her memoir, That's All I Wanted. Chang's book, filled with funny and engaging characters, is brought to life through this performance. Fans will enjoy experiencing Chang's brilliance in person, while newcomers to her work will receive a {{Q}} introduction to her entertaining world.\n\nShow times are Thursday through Sunday at 7:00 P.M., with an additional matinee on Saturday at 1:00 P.M. [ … ]. Additional information can be found at www.lostoceantheater.com.", "q": "Chọn đáp án điền vào chỗ trống (141) trong đoạn văn.", "choices": ["delight", "delights", "delighted", "delightful"], "correct": 3, "explain": "Dịch: Người mới biết đến tác phẩm của cô sẽ có một màn giới thiệu thú vị. — Giữa \"a\" và danh từ \"introduction\" cần tính từ → \"delightful\".", "src": "ETS 2026 · Test 4 · Câu 141"}, {"t": 4, "n": 145, "topic": "tu-loai", "title": "E-mail", "passage": "I left a complimentary floral arrangement with your receptionist today, and she suggested that I contact you directly. I specialize in floral design. I created this bouquet for you, using bold colors that match the inn's lobby, to give you an idea of how I approach my work.\n\nI was told that you do not currently have a budget for décor. Even so, perhaps we could still partner in some way. I see that you host small events, and your Web site has links to local DJs, caterers, and other service providers that you recommend. Would you consider including my company, Petals Aplenty, on your list of {{Q}}? I would be happy to reciprocate by promoting your inn on my own Web site. [ … ].\n\nI look forward to hearing from you.", "q": "Chọn đáp án điền vào chỗ trống (145) trong đoạn văn.", "choices": ["refers", "referred", "referrals", "referable"], "correct": 2, "explain": "Dịch: Bạn có cân nhắc đưa công ty tôi vào danh sách đơn vị được giới thiệu không? — Sau \"your list of\" cần danh từ số nhiều → \"referrals\".", "src": "ETS 2026 · Test 4 · Câu 145"}, {"t": 5, "n": 103, "topic": "tu-loai", "q": "Operating instructions for the printer will be e-mailed to employees -------.", "choices": ["short", "shortly", "shorter", "shortening"], "correct": 1, "explain": "Dịch: Hướng dẫn sử dụng máy in sẽ sớm được gửi email cho nhân viên. — Cuối câu bổ nghĩa cho động từ \"will be e-mailed\" → trạng từ \"shortly\" (= soon).", "src": "ETS 2026 · Test 5 · Câu 103"}, {"t": 5, "n": 104, "topic": "tu-loai", "q": "Dozens of ------- customers have posted positive reviews of Stellenbosch Cycle Works.", "choices": ["satisfy", "satisfied", "satisfaction", "satisfies"], "correct": 1, "explain": "Dịch: Hàng chục khách hàng hài lòng đã đăng nhận xét tốt. — Trước danh từ \"customers\" cần tính từ; người cảm thấy hài lòng → \"satisfied\".", "src": "ETS 2026 · Test 5 · Câu 104"}, {"t": 5, "n": 108, "topic": "tu-loai", "q": "Mr. Lenthe will distribute ------- of the workshop agenda to all managers by Tuesday morning.", "choices": ["copies", "copier", "copy", "copying"], "correct": 0, "explain": "Dịch: Ông Lenthe sẽ phát bản sao chương trình hội thảo cho mọi quản lý. — Tân ngữ của \"distribute\", không mạo từ → danh từ số nhiều \"copies\".", "src": "ETS 2026 · Test 5 · Câu 108"}, {"t": 5, "n": 110, "topic": "tu-loai", "q": "Managers at Afton Accounting are urged to provide ------- feedback to employees on a regular basis.", "choices": ["construct", "constructor", "constructive", "construction"], "correct": 2, "explain": "Dịch: Quản lý được khuyến khích góp ý mang tính xây dựng cho nhân viên thường xuyên. — Trước danh từ \"feedback\" cần tính từ → \"constructive\".", "src": "ETS 2026 · Test 5 · Câu 110"}, {"t": 5, "n": 112, "topic": "tu-loai", "q": "------- in the housing market has continued to drag down real estate profits.", "choices": ["Weak", "Weakly", "Weakness", "Weakened"], "correct": 2, "explain": "Dịch: Sự yếu kém của thị trường nhà đất tiếp tục kéo giảm lợi nhuận. — Đầu câu làm chủ ngữ, trước \"in the housing market\" → danh từ \"Weakness\".", "src": "ETS 2026 · Test 5 · Câu 112"}, {"t": 5, "n": 116, "topic": "tu-loai", "q": "The department supervisor is ------- for ensuring that all safety gear is stowed properly at the end of the shift.", "choices": ["responsibilities", "responsibility", "responsibly", "responsible"], "correct": 3, "explain": "Dịch: Tổ trưởng chịu trách nhiệm bảo đảm đồ bảo hộ được cất đúng chỗ. — \"be responsible for + V-ing\": sau \"is\" cần tính từ → \"responsible\".", "src": "ETS 2026 · Test 5 · Câu 116"}, {"t": 5, "n": 118, "topic": "tu-loai", "q": "The experiment's initial results were ------- different from what was expected.", "choices": ["wild", "wildest", "wildly", "wildness"], "correct": 2, "explain": "Dịch: Kết quả ban đầu khác rất xa so với dự kiến. — Trước tính từ \"different\" cần trạng từ → \"wildly\".", "src": "ETS 2026 · Test 5 · Câu 118"}, {"t": 5, "n": 120, "topic": "tu-loai", "q": "The spray-on sealant ------- as a protective layer that keeps your tiles from getting scratched.", "choices": ["acts", "acting", "action", "actively"], "correct": 0, "explain": "Dịch: Lớp phủ dạng xịt đóng vai trò lớp bảo vệ giúp gạch không bị trầy. — Câu thiếu động từ chính, chủ ngữ số ít \"The spray-on sealant\" → \"acts\" (act as = đóng vai trò).", "src": "ETS 2026 · Test 5 · Câu 120"}, {"t": 1, "n": 136, "topic": "cac-thi", "title": "Letter", "passage": "Dear Ms. Mulligan,\n\nWe are delighted to celebrate your 30th anniversary with Brandrix Distribution Centre. [ … ] Your dedication, loyalty, and hard work have contributed greatly to our success over the years. We appreciate your commitment to excellence. Over the years, you {{Q}} great initiative, creativity, and leadership.\n\nYou will soon be receiving a commemorative plaque by post. We hope this token of our gratitude reminds you how much you mean to us.", "q": "Chọn đáp án điền vào chỗ trống (136) trong đoạn văn.", "choices": ["will show", "must show", "have shown", "are showing"], "correct": 2, "explain": "Dịch: Suốt nhiều năm qua, chị đã thể hiện sự chủ động, sáng tạo và khả năng lãnh đạo. — \"Over the years\" (tính đến nay) → hiện tại hoàn thành \"have shown\".", "src": "ETS 2026 · Test 1 · Câu 136"}, {"t": 2, "n": 120, "topic": "cac-thi", "q": "Management ------- candidates for promotion by the end of the month.", "choices": ["identify", "identifying", "will identify", "to identify"], "correct": 2, "explain": "Dịch: Ban quản lý sẽ chọn ứng viên thăng chức trước cuối tháng. — Câu thiếu động từ chính; \"by the end of the month\" chỉ tương lai → \"will identify\". \"identify\" sai vì \"Management\" coi là số ít và sai thì.", "src": "ETS 2026 · Test 2 · Câu 120"}, {"t": 2, "n": 139, "topic": "cac-thi", "title": "Article", "passage": "Moortap Bistro Plans to Close Its Doors\n\nWhen Rowena Ellison opened the Moortap Bistro in a remote village in the Downland Moors, she wanted to attract customers from larger towns. She {{Q}} an unusual menu of local dishes prepared with less familiar ingredients, all in a beautiful setting. Her plan worked.\n\nThe eatery became one of the area's most successful venues and remains so now. At this point, though, Ellison says she is ready to close the bistro and retire.", "q": "Chọn đáp án điền vào chỗ trống (139) trong đoạn văn.", "choices": ["offers", "offered", "will offer", "is offering"], "correct": 1, "explain": "Dịch: Bà ấy đã đưa ra thực đơn món địa phương độc đáo… Kế hoạch của bà đã thành công. — Kể chuyện quá khứ (opened, wanted, worked) → \"offered\".", "src": "ETS 2026 · Test 2 · Câu 139"}, {"t": 3, "n": 112, "topic": "cac-thi", "q": "Dr. Cheung ------- Silk Valley Hospital at next weekend's medical fair.", "choices": ["represent", "did represent", "is representing", "had represented"], "correct": 2, "explain": "Dịch: Tiến sĩ Cheung sẽ đại diện Bệnh viện Silk Valley tại hội chợ y tế cuối tuần tới. — Kế hoạch đã định trong tương lai gần (next weekend) → hiện tại tiếp diễn \"is representing\".", "src": "ETS 2026 · Test 3 · Câu 112"}, {"t": 3, "n": 129, "topic": "cac-thi", "q": "Long before the training program began, Ms. Morris ------- the schedule to allow her team to attend.", "choices": ["was revised", "is revising", "had revised", "has to revise"], "correct": 2, "explain": "Dịch: Rất lâu trước khi khoá đào tạo bắt đầu, cô Morris đã chỉnh lịch để nhóm có thể tham dự. — Hành động xảy ra trước một hành động khác trong quá khứ (\"Long before … began\") → \"had revised\".", "src": "ETS 2026 · Test 3 · Câu 129"}, {"t": 3, "n": 144, "topic": "cac-thi", "title": "E-mail", "passage": "Botswana Mining's online payroll portal will be unavailable between 8 and 12 April to allow for a software upgrade. Please refrain from accessing the system over these five days.\n\nThe updated site {{Q}} users to perform advanced operations, including setting up and managing direct deposit preferences and accessing tax documents. It will also feature a live-chat function so that users can directly contact a human resources team member when needed. [ … ].\n\nIf you need to access your payroll and benefits details during the period mentioned above, please send an e-mail to hr@botswanamining.co.bw or visit our office in room 107 of the Ujima Tower.", "q": "Chọn đáp án điền vào chỗ trống (144) trong đoạn văn.", "choices": ["enabled", "enabling", "will enable", "would have enabled"], "correct": 2, "explain": "Dịch: Trang web sau nâng cấp sẽ cho phép người dùng thực hiện các thao tác nâng cao. — Nói về trang sẽ có sau đợt nâng cấp (câu sau \"It will also feature\") → \"will enable\".", "src": "ETS 2026 · Test 3 · Câu 144"}, {"t": 4, "n": 107, "topic": "cac-thi", "q": "Once Ms. Jeong ------- the contract, she will sign and return it to Allory Pharmaceuticals.", "choices": ["to receive", "receives", "was received", "receiving"], "correct": 1, "explain": "Dịch: Khi cô Jeong nhận được hợp đồng, cô sẽ ký và gửi lại. — Mệnh đề thời gian sau \"Once/When\" dùng hiện tại đơn thay cho tương lai → \"receives\".", "src": "ETS 2026 · Test 4 · Câu 107"}, {"t": 4, "n": 131, "topic": "cac-thi", "title": "Article", "passage": "New Vietnamese Restaurant Opens\n\nSAN FRANCISCO (November 5)--Celebrity chef Eric Hoang {{Q}} his first restaurant, Ngon Mieng. It opened last week in the North Beach neighborhood. Ngon Mieng serves authentic Vietnamese cuisine and some innovative dishes developed by Chef Hoang. The restaurant took over the space once occupied by the restaurant Plantains, which closed last year.\n\nChef Hoang won first place on the reality television show Best Chefs in the U.S. two years ago. [ … ]. \"After receiving the award, opening a restaurant became my dream,\" he said. \"I am excited to bring my culinary creations to the North Beach area.\"", "q": "Chọn đáp án điền vào chỗ trống (131) trong đoạn văn.", "choices": ["will launch", "could launch", "has launched", "was launching"], "correct": 2, "explain": "Dịch: Đầu bếp nổi tiếng Eric Hoang vừa khai trương nhà hàng đầu tiên. Nhà hàng mở cửa tuần trước. — Tin mới, kết quả còn ở hiện tại → hiện tại hoàn thành \"has launched\".", "src": "ETS 2026 · Test 4 · Câu 131"}, {"t": 4, "n": 139, "topic": "cac-thi", "title": "Announcement", "passage": "Lost Ocean Theater is thrilled to announce a unique offering coming to its downtown location next week. The talented comedian Maddy Chang {{Q}} a one-person show based on her memoir, That's All I Wanted. Chang's book, filled with funny and engaging characters, is brought to life through this performance. Fans will enjoy experiencing Chang's brilliance in person, while newcomers to her work will receive a delightful introduction to her entertaining world.\n\nShow times are Thursday through Sunday at 7:00 P.M., with an additional matinee on Saturday at 1:00 P.M. [ … ]. Additional information can be found at www.lostoceantheater.com.", "q": "Chọn đáp án điền vào chỗ trống (139) trong đoạn văn.", "choices": ["will perform", "to perform", "performed", "performing"], "correct": 0, "explain": "Dịch: Nghệ sĩ hài Maddy Chang sẽ biểu diễn một chương trình độc diễn… — Thông báo sự kiện \"coming … next week\" → tương lai \"will perform\".", "src": "ETS 2026 · Test 4 · Câu 139"}, {"t": 5, "n": 134, "topic": "cac-thi", "title": "E-mail", "passage": "As many of you have recently learned, Claudia Hoffman will end her tenure as art director on Monday, December 30. After ten years in this role, she will be taking on a new professional challenge in Paris. There, she will join the leadership team at a top advertising agency. Marcos Molina from Spencer Design will become our new art director. [ … ].\n\nI would like to personally thank Ms. Hoffman for her tremendous leadership. She {{Q}} a key factor in our agency's success. Please join me in celebrating her achievements at a farewell dinner after work hours on Friday, December 27. The details will be forthcoming.\n\nSincerely,", "q": "Chọn đáp án điền vào chỗ trống (134) trong đoạn văn.", "choices": ["will be", "could be", "has been", "would have been"], "correct": 2, "explain": "Dịch: Bà ấy là nhân tố then chốt trong thành công của công ty. — Bà đã làm việc ở đây mười năm và sắp rời đi: sự đóng góp kéo dài từ quá khứ đến nay → hiện tại hoàn thành \"has been\".", "src": "ETS 2026 · Test 5 · Câu 134"}, {"t": 5, "n": 137, "topic": "cac-thi", "title": "Booklet", "passage": "Your success as a team leader depends on your ability to consistently inspire your team members to perform at the highest level. Good leaders know how to find viable solutions to workplace problems and implement them accordingly. [ … ]. How can you gain these skills?\n\nIn this seminar, you {{Q}} how to better align your team members' performance with your organization's goals. Participants in the seminar acquire proven tools and techniques for successfully directing a team in today's fast-paced business environment.", "q": "Chọn đáp án điền vào chỗ trống (137) trong đoạn văn.", "choices": ["learned", "will learn", "had learned", "will have learned"], "correct": 1, "explain": "Dịch: Trong buổi hội thảo này, bạn sẽ học cách gắn kết hiệu suất nhóm với mục tiêu tổ chức. — Quảng cáo hội thảo sắp diễn ra → tương lai đơn \"will learn\".", "src": "ETS 2026 · Test 5 · Câu 137"}, {"t": 5, "n": 124, "topic": "chia-dong-tu", "q": "Posting updates too infrequently on social media can cause small businesses ------- by their customers.", "choices": ["forgets", "to forget", "been forgotten", "to be forgotten"], "correct": 3, "explain": "Dịch: Đăng bài quá thưa trên mạng xã hội có thể khiến doanh nghiệp nhỏ bị khách hàng lãng quên. — \"cause + O + to V\"; doanh nghiệp \"bị quên\" (có \"by their customers\") → bị động \"to be forgotten\".", "src": "ETS 2026 · Test 5 · Câu 124"}, {"t": 1, "n": 109, "topic": "hoa-hop-chu-vi", "q": "Dynart, Inc., continuously ------- new ways to reduce its use of plastics.", "choices": ["seeks", "seeker", "to seek", "seeking"], "correct": 0, "explain": "Dịch: Dynart liên tục tìm cách mới để giảm dùng nhựa. — Câu thiếu động từ chính; chủ ngữ là tên công ty (số ít) → \"seeks\".", "src": "ETS 2026 · Test 1 · Câu 109"}, {"t": 2, "n": 114, "topic": "hoa-hop-chu-vi", "q": "Central Science Museum hosts online seminars by experts who ------- topics related to information technology.", "choices": ["are covered", "covering", "to cover", "cover"], "correct": 3, "explain": "Dịch: Bảo tàng tổ chức hội thảo trực tuyến của các chuyên gia trình bày về công nghệ thông tin. — Mệnh đề \"who ___ topics\" thiếu động từ; \"who\" thay cho \"experts\" (số nhiều), chủ động → \"cover\".", "src": "ETS 2026 · Test 2 · Câu 114"}, {"t": 3, "n": 118, "topic": "hoa-hop-chu-vi", "q": "The results of the study suggest that more people ------- with night driving than previously believed.", "choices": ["struggles", "struggling", "to struggle", "struggle"], "correct": 3, "explain": "Dịch: Nghiên cứu cho thấy nhiều người gặp khó khi lái xe ban đêm hơn ta tưởng. — Mệnh đề \"that more people ___\" thiếu động từ; \"people\" số nhiều → \"struggle\".", "src": "ETS 2026 · Test 3 · Câu 118"}, {"t": 1, "n": 104, "topic": "dai-tu", "q": "As a result of ------- many years leading media organizations, Ms. Ayo was selected for the Dowel Journalism Prize.", "choices": ["she", "her", "hers", "herself"], "correct": 1, "explain": "Dịch: Nhờ nhiều năm lãnh đạo các tổ chức truyền thông, bà Ayo được chọn nhận giải Báo chí Dowel. — Trước cụm danh từ \"many years\" cần tính từ sở hữu → \"her\".", "src": "ETS 2026 · Test 1 · Câu 104"}, {"t": 1, "n": 134, "topic": "dai-tu", "title": "Flyer", "passage": "Look to Riessler Landscaping for your Garden Needs\n\nRiessler Landscaping has everything you need to create your dream garden. We will listen to your ideas and offer suggestions that match your gardening desires. [ … ] The nursery here at Riessler Landscaping includes plants of many varieties and sizes that burst with eye-catching colors year-round. You are guaranteed to find something that will add beauty to your garden. We are also equipped to construct small ponds or other water features. And as our name suggests, we can take on more ambitious landscaping projects—whatever you need! With more than 40 years in the landscape–design business, {{Q}} expertise is unmatched.", "q": "Chọn đáp án điền vào chỗ trống (134) trong đoạn văn.", "choices": ["its", "our", "others", "their"], "correct": 1, "explain": "Dịch: Với hơn 40 năm trong ngành thiết kế cảnh quan, chuyên môn của chúng tôi không ai sánh bằng. — Cả tờ rơi xưng \"We\" (We will listen…, We are equipped…) → tính từ sở hữu \"our\". Bẫy: \"its\" nếu chỉ nhìn tên công ty.", "src": "ETS 2026 · Test 1 · Câu 134"}, {"t": 1, "n": 142, "topic": "dai-tu", "title": "E-mail", "passage": "My design team is in the process of finalizing the plans for your living room. Based on our last conversation, I have chosen different paints for the walls and borders. Please review the attached file and decide whether you like those new colors. If not, it is not too late to make a change. [ … ] Your review will help us refine the design before we start.\n\nPlease let {{Q}} know if you have any questions. I look forward to hearing from you.\n\nKind regards,\nAli Chaleby, Ralencia Design", "q": "Chọn đáp án điền vào chỗ trống (142) trong đoạn văn.", "choices": ["them", "ours", "his", "me"], "correct": 3, "explain": "Dịch: Vui lòng cho tôi biết nếu bà có câu hỏi. — \"let + tân ngữ + V0\": người viết thư xưng \"I\" (I look forward…) → tân ngữ \"me\".", "src": "ETS 2026 · Test 1 · Câu 142"}, {"t": 2, "n": 104, "topic": "dai-tu", "q": "Reimbursement for travel expenses will be included in ------- October 1 paycheck.", "choices": ["you", "your", "yours", "yourself"], "correct": 1, "explain": "Dịch: Tiền hoàn công tác phí sẽ có trong phiếu lương ngày 1/10 của bạn. — Trước cụm danh từ \"October 1 paycheck\" cần tính từ sở hữu \"your\".", "src": "ETS 2026 · Test 2 · Câu 104"}, {"t": 2, "n": 110, "topic": "dai-tu", "q": "Although ------- training has just begun, Ms. Yu has already mastered the company's proprietary accounting software.", "choices": ["her", "she", "hers", "herself"], "correct": 0, "explain": "Dịch: Dù việc đào tạo của cô ấy mới bắt đầu, cô Yu đã thành thạo phần mềm kế toán riêng của công ty. — Trước danh từ \"training\" cần tính từ sở hữu \"her\".", "src": "ETS 2026 · Test 2 · Câu 110"}, {"t": 3, "n": 101, "topic": "dai-tu", "q": "Despite ------- youth, Ms. Cho is already quite popular on social media.", "choices": ["she", "her", "hers", "herself"], "correct": 1, "explain": "Dịch: Dù còn trẻ, cô Cho đã khá nổi tiếng trên mạng xã hội. — Sau giới từ \"Despite\" là cụm danh từ; trước danh từ \"youth\" cần tính từ sở hữu \"her\".", "src": "ETS 2026 · Test 3 · Câu 101"}, {"t": 4, "n": 101, "topic": "dai-tu", "q": "Ms. Chiu recently announced that ------- is planning to retire in September.", "choices": ["her", "hers", "herself", "she"], "correct": 3, "explain": "Dịch: Bà Chiu vừa thông báo rằng bà dự định nghỉ hưu vào tháng Chín. — Mệnh đề \"that ___ is planning\" thiếu chủ ngữ → đại từ chủ ngữ \"she\".", "src": "ETS 2026 · Test 4 · Câu 101"}, {"t": 5, "n": 106, "topic": "dai-tu", "q": "The marketing manager, Ms. Abyola, plans to meet with the press following ------- meeting with the vice president.", "choices": ["her", "she", "hers", "herself"], "correct": 0, "explain": "Dịch: Trưởng phòng marketing dự định gặp báo chí sau cuộc họp của bà với phó chủ tịch. — Trước danh từ \"meeting\" cần tính từ sở hữu \"her\".", "src": "ETS 2026 · Test 5 · Câu 106"}, {"t": 5, "n": 128, "topic": "dai-tu", "q": "Belker Auto offers a ten-year warranty for ------- who want greater peace of mind.", "choices": ["this", "those", "somebody", "everyone"], "correct": 1, "explain": "Dịch: Belker Auto bảo hành mười năm cho những ai muốn yên tâm hơn. — \"those who + V số nhiều\" = những người mà.", "src": "ETS 2026 · Test 5 · Câu 128"}, {"t": 1, "n": 101, "topic": "gioi-tu-lien-tu", "q": "The lecture will take place at 6:00 P.M., ------- which attendees may ask questions.", "choices": ["across", "after", "inside", "among"], "correct": 1, "explain": "Dịch: Bài giảng diễn ra lúc 6 giờ chiều, sau đó người tham dự có thể đặt câu hỏi. — \"after which\" = sau sự việc đó (giới từ + which thay cho cả mệnh đề trước). across/inside/among chỉ nơi chốn, không hợp nghĩa thời gian.", "src": "ETS 2026 · Test 1 · Câu 101"}, {"t": 1, "n": 107, "topic": "gioi-tu-lien-tu", "q": "In October, Mr. Sakamoto will leave for New Zealand ------- will oversee the opening of the new Auckland branch.", "choices": ["because", "in addition", "and", "prior to"], "correct": 2, "explain": "Dịch: Tháng Mười, ông Sakamoto sẽ sang New Zealand và giám sát việc khai trương chi nhánh Auckland. — Hai động từ cùng chủ ngữ (will leave … will oversee) nối bằng liên từ đẳng lập \"and\".", "src": "ETS 2026 · Test 1 · Câu 107"}, {"t": 1, "n": 117, "topic": "gioi-tu-lien-tu", "q": "The board of directors has voted to award Mr. Mitrakos a bonus for his role ------- obtaining the international contract.", "choices": ["in", "at", "except", "apart"], "correct": 0, "explain": "Dịch: HĐQT đã biểu quyết thưởng cho ông Mitrakos vì vai trò của ông trong việc giành hợp đồng quốc tế. — Cụm cố định \"role in + V-ing/danh từ\" (vai trò trong việc gì).", "src": "ETS 2026 · Test 1 · Câu 117"}, {"t": 1, "n": 118, "topic": "gioi-tu-lien-tu", "q": "The finance director gave his approval ------- the project can move forward.", "choices": ["along", "furthermore", "cautiously", "so that"], "correct": 3, "explain": "Dịch: Giám đốc tài chính đã duyệt để dự án có thể tiến hành. — \"so that + mệnh đề (can/could)\" = để mà, chỉ mục đích.", "src": "ETS 2026 · Test 1 · Câu 118"}, {"t": 1, "n": 121, "topic": "gioi-tu-lien-tu", "q": "Ennis Photography purchased all new lighting equipment ------- the high cost.", "choices": ["even though", "however", "until", "despite"], "correct": 3, "explain": "Dịch: Ennis Photography đã mua toàn bộ thiết bị chiếu sáng mới bất chấp chi phí cao. — Sau chỗ trống là cụm danh từ (the high cost) → cần giới từ \"despite\". \"even though\" là liên từ, phải theo sau là mệnh đề S + V.", "src": "ETS 2026 · Test 1 · Câu 121"}, {"t": 1, "n": 128, "topic": "gioi-tu-lien-tu", "q": "Milltown Hospital's cafeteria serves lunch seven days a week ------- only on weekdays.", "choices": ["up to", "as though", "each time", "rather than"], "correct": 3, "explain": "Dịch: Căng tin bệnh viện phục vụ bữa trưa cả bảy ngày thay vì chỉ các ngày trong tuần. — \"rather than\" nối hai thành phần song song: seven days a week / only on weekdays.", "src": "ETS 2026 · Test 1 · Câu 128"}, {"t": 2, "n": 101, "topic": "gioi-tu-lien-tu", "q": "The all-new Amore sports sedan is engineered for maximum reliability ------- gas mileage.", "choices": ["so", "but", "and", "nor"], "correct": 2, "explain": "Dịch: Mẫu sedan Amore được thiết kế để tối đa độ bền và tiết kiệm xăng. — Hai danh từ cùng ý bổ sung → \"and\". \"nor\" dùng sau phủ định; \"but\" đối lập.", "src": "ETS 2026 · Test 2 · Câu 101"}, {"t": 2, "n": 107, "topic": "gioi-tu-lien-tu", "q": "Please remove the boxes left in the staff lounge ------- 5 P.M.", "choices": ["of", "to", "as", "by"], "correct": 3, "explain": "Dịch: Vui lòng dọn các thùng để trong phòng nghỉ nhân viên trước 5 giờ chiều. — \"by + mốc thời gian\" = chậm nhất là lúc đó (hạn chót).", "src": "ETS 2026 · Test 2 · Câu 107"}, {"t": 2, "n": 119, "topic": "gioi-tu-lien-tu", "q": "Mortgage brokers generally prefer to review all the financial documents ------- meeting with a new client.", "choices": ["toward", "further", "lately", "before"], "correct": 3, "explain": "Dịch: Môi giới thế chấp thường thích xem toàn bộ giấy tờ tài chính trước khi gặp khách hàng mới. — \"before + V-ing\" (trước khi làm gì).", "src": "ETS 2026 · Test 2 · Câu 119"}, {"t": 2, "n": 123, "topic": "gioi-tu-lien-tu", "q": "Farist Bakery, which specializes in dessert catering, is located ------- the Liverpool Convention Complex.", "choices": ["near", "without", "since", "following"], "correct": 0, "explain": "Dịch: Tiệm bánh Farist, chuyên phục vụ tiệc tráng miệng, nằm gần Khu hội nghị Liverpool. — \"be located near + địa điểm\" (nằm gần). without/since/following không chỉ vị trí.", "src": "ETS 2026 · Test 2 · Câu 123"}, {"t": 2, "n": 130, "topic": "gioi-tu-lien-tu", "q": "------- it is occasionally inconvenient, Mr. Ohtani expects all team members to attend his weekly meeting.", "choices": ["Though", "As soon as", "Because", "When"], "correct": 0, "explain": "Dịch: Dù đôi khi bất tiện, ông Ohtani vẫn yêu cầu mọi thành viên dự họp hằng tuần. — Hai vế trái ngược (bất tiện >< vẫn yêu cầu) → liên từ nhượng bộ \"Though\" + mệnh đề.", "src": "ETS 2026 · Test 2 · Câu 130"}, {"t": 2, "n": 146, "topic": "gioi-tu-lien-tu", "title": "E-mail", "passage": "As noted during the visit, the current driveway contains several low spots where water collects during heavy rains. We could address this drainage issue in several ways. The first would be to patch the low spots with filler. Alternatively, we could remove all of the old asphalt and replace it with a porous material such as crushed gravel. [ … ]. A gravel bed allows rainwater to pass into the underlying soil and be reabsorbed.\n\nPlease give me a call {{Q}} it is convenient so that we can talk about next steps.\n\nBrooks Hunley\nCarlton Ames Paving", "q": "Chọn đáp án điền vào chỗ trống (146) trong đoạn văn.", "choices": ["yet", "whenever", "until", "besides"], "correct": 1, "explain": "Dịch: Hãy gọi cho tôi bất cứ khi nào thuận tiện để chúng ta bàn bước tiếp theo. — \"whenever it is convenient\" = bất cứ lúc nào (anh/chị) tiện. Đây là cụm rất hay gặp cuối thư.", "src": "ETS 2026 · Test 2 · Câu 146"}, {"t": 3, "n": 110, "topic": "gioi-tu-lien-tu", "q": "Ahearn Accessories' retail shop is located ------- Gordon Avenue and Hutch Street.", "choices": ["until", "against", "at", "aside from"], "correct": 2, "explain": "Dịch: Cửa hàng của Ahearn Accessories nằm ở giao lộ đại lộ Gordon và phố Hutch. — \"at + giao lộ hai con đường\" (at A and B). Giới từ \"at\" cho điểm cụ thể.", "src": "ETS 2026 · Test 3 · Câu 110"}, {"t": 3, "n": 124, "topic": "gioi-tu-lien-tu", "q": "------- the hotel does not have a restaurant on site, there are many dining options nearby.", "choices": ["While", "Such as", "Unless", "Without"], "correct": 0, "explain": "Dịch: Mặc dù khách sạn không có nhà hàng, gần đó có nhiều lựa chọn ăn uống. — Sau chỗ trống là mệnh đề + ý tương phản → liên từ \"While\" (= although). \"Such as/Without\" là giới từ; \"Unless\" (trừ khi) sai nghĩa.", "src": "ETS 2026 · Test 3 · Câu 124"}, {"t": 3, "n": 125, "topic": "gioi-tu-lien-tu", "q": "------- a slight decline in revenue from the previous quarter, Blakely Components is moving forward with its expansion plan.", "choices": ["Aside", "Despite", "Becoming", "Often"], "correct": 1, "explain": "Dịch: Dù doanh thu giảm nhẹ so với quý trước, Blakely vẫn tiếp tục kế hoạch mở rộng. — Cụm danh từ + ý trái ngược → \"Despite\". \"Aside\" phải là \"Aside from\".", "src": "ETS 2026 · Test 3 · Câu 125"}, {"t": 3, "n": 126, "topic": "gioi-tu-lien-tu", "q": "Abelia Dairy Company has undergone several changes in leadership ------- the past ten years.", "choices": ["over", "into", "since", "beside"], "correct": 0, "explain": "Dịch: Công ty sữa Abelia đã trải qua nhiều lần thay đổi lãnh đạo trong mười năm qua. — \"over the past + khoảng thời gian\" đi với thì hiện tại hoàn thành. \"since\" phải đi với mốc thời gian (since 2015), không đi với \"the past ten years\".", "src": "ETS 2026 · Test 3 · Câu 126"}, {"t": 3, "n": 130, "topic": "gioi-tu-lien-tu", "q": "Mr. Swan will return to the planning meeting ------- the interns have arrived.", "choices": ["once", "unlike", "whereas", "regarding"], "correct": 0, "explain": "Dịch: Ông Swan sẽ quay lại cuộc họp kế hoạch một khi các thực tập sinh đã đến. — Sau chỗ trống là mệnh đề chỉ thời gian → liên từ \"once\" (một khi). unlike/regarding là giới từ; whereas (trong khi đó) chỉ tương phản.", "src": "ETS 2026 · Test 3 · Câu 130"}, {"t": 4, "n": 102, "topic": "gioi-tu-lien-tu", "q": "Mr. Kashnitz will interview the applicants ------- the holiday.", "choices": ["above", "before", "among", "along"], "correct": 1, "explain": "Dịch: Ông Kashnitz sẽ phỏng vấn ứng viên trước kỳ nghỉ lễ. — \"before + mốc thời gian/sự kiện\". above/among/along chỉ vị trí.", "src": "ETS 2026 · Test 4 · Câu 102"}, {"t": 4, "n": 112, "topic": "gioi-tu-lien-tu", "q": "The posters must be completed soon ------- they can be put up in advance of the gala.", "choices": ["so that", "despite", "whenever", "as if"], "correct": 0, "explain": "Dịch: Áp phích phải hoàn thành sớm để có thể treo trước buổi dạ tiệc. — \"so that + S + can + V\" chỉ mục đích.", "src": "ETS 2026 · Test 4 · Câu 112"}, {"t": 4, "n": 114, "topic": "gioi-tu-lien-tu", "q": "------- weeks of record-setting rain, expect only blue skies this weekend.", "choices": ["After", "Besides", "Opposite", "Alongside"], "correct": 0, "explain": "Dịch: Sau nhiều tuần mưa kỷ lục, cuối tuần này trời sẽ quang đãng. — \"After + cụm danh từ\" chỉ thời gian.", "src": "ETS 2026 · Test 4 · Câu 114"}, {"t": 4, "n": 125, "topic": "gioi-tu-lien-tu", "q": "In celebration of Ms. Tseng's promotion, tea and cookies will be served ------- the meeting.", "choices": ["later", "as soon as", "following", "in case of"], "correct": 2, "explain": "Dịch: Mừng bà Tseng thăng chức, trà và bánh sẽ được phục vụ sau cuộc họp. — Giới từ \"following\" (= after) + danh từ. \"as soon as\" cần mệnh đề; \"later\" là trạng từ.", "src": "ETS 2026 · Test 4 · Câu 125"}, {"t": 4, "n": 130, "topic": "gioi-tu-lien-tu", "q": "During checkout, cashiers must be able to scan purchased items accurately ------- field questions from customers.", "choices": ["but", "for instance", "although", "as well as"], "correct": 3, "explain": "Dịch: Khi thanh toán, thu ngân phải quét hàng chính xác cũng như trả lời câu hỏi của khách. — \"as well as\" nối hai động từ cùng dạng (scan … as well as field …). \"but\" mang nghĩa đối lập, \"although\" cần mệnh đề.", "src": "ETS 2026 · Test 4 · Câu 130"}, {"t": 5, "n": 101, "topic": "gioi-tu-lien-tu", "q": "Mr. Choi, who recently joined the advisory board, is an experienced accountant ------- investor.", "choices": ["but", "that", "and", "yet"], "correct": 2, "explain": "Dịch: Ông Choi là một kế toán và nhà đầu tư giàu kinh nghiệm. — Hai danh từ chỉ cùng một người nối bằng \"and\" (an experienced accountant and investor).", "src": "ETS 2026 · Test 5 · Câu 101"}, {"t": 5, "n": 109, "topic": "gioi-tu-lien-tu", "q": "Employees are eligible for more vacation time ------- they have been employed for five years.", "choices": ["after", "neither", "so", "thus"], "correct": 0, "explain": "Dịch: Nhân viên được thêm ngày phép sau khi làm việc đủ năm năm. — Liên từ thời gian \"after\" + mệnh đề.", "src": "ETS 2026 · Test 5 · Câu 109"}, {"t": 5, "n": 119, "topic": "gioi-tu-lien-tu", "q": "------- critical reviews, the movie was a great success at the box office.", "choices": ["During", "About", "Despite", "Over"], "correct": 2, "explain": "Dịch: Bất chấp những lời chê từ giới phê bình, bộ phim vẫn rất thành công về doanh thu. — Danh từ \"critical reviews\" + ý trái ngược → giới từ \"Despite\".", "src": "ETS 2026 · Test 5 · Câu 119"}, {"t": 5, "n": 121, "topic": "gioi-tu-lien-tu", "q": "The contract for the renovation of the park will not be awarded ------- all bids have been submitted.", "choices": ["nor", "next", "until", "because"], "correct": 2, "explain": "Dịch: Hợp đồng cải tạo công viên sẽ chưa được trao cho đến khi nhận đủ hồ sơ thầu. — \"not … until\" = mãi đến khi … mới.", "src": "ETS 2026 · Test 5 · Câu 121"}, {"t": 5, "n": 123, "topic": "gioi-tu-lien-tu", "q": "Margie Fung was ------- the winners at Sternetz Institute's art competition.", "choices": ["from", "upon", "among", "beyond"], "correct": 2, "explain": "Dịch: Margie Fung là một trong những người thắng cuộc thi nghệ thuật. — \"among + danh từ số nhiều\" = (là một) trong số.", "src": "ETS 2026 · Test 5 · Câu 123"}, {"t": 2, "n": 124, "topic": "so-sanh", "q": "The presentations were ------- than we expected, so there was ample time left for questions.", "choices": ["brief", "briefly", "briefer", "briefest"], "correct": 2, "explain": "Dịch: Các bài thuyết trình ngắn hơn chúng tôi dự đoán nên còn nhiều thời gian hỏi đáp. — Có \"than\" → so sánh hơn \"briefer\".", "src": "ETS 2026 · Test 2 · Câu 124"}, {"t": 5, "n": 114, "topic": "so-sanh", "q": "Of all the mistakes people make in the office, not proofreading their e-mails is one of the -------.", "choices": ["commoners", "most common", "in common", "more commonly"], "correct": 1, "explain": "Dịch: Trong mọi lỗi ở văn phòng, không đọc soát email là một trong những lỗi phổ biến nhất. — \"one of the + so sánh nhất (+ danh từ số nhiều)\" → \"most common\".", "src": "ETS 2026 · Test 5 · Câu 114"}, {"t": 2, "n": 117, "topic": "menh-de-quan-he", "q": "All of our tablet computers come with a one-year warranty ------- includes hardware repairs and replacements.", "choices": ["that", "who", "what", "it"], "correct": 0, "explain": "Dịch: Mọi máy tính bảng của chúng tôi đều kèm bảo hành một năm bao gồm sửa chữa và thay phần cứng. — Tiền ngữ là vật (warranty), đại từ quan hệ làm chủ ngữ → \"that/which\". \"who\" dùng cho người; \"it\" không nối được mệnh đề.", "src": "ETS 2026 · Test 2 · Câu 117"}, {"t": 3, "n": 116, "topic": "menh-de-quan-he", "q": "The committee members ------- attended the meeting are listed in the appendix.", "choices": ["who", "they", "when", "some"], "correct": 0, "explain": "Dịch: Các thành viên uỷ ban đã dự họp được liệt kê ở phụ lục. — Tiền ngữ chỉ người (members), cần chủ ngữ cho \"attended\" → \"who\".", "src": "ETS 2026 · Test 3 · Câu 116"}, {"t": 4, "n": 117, "topic": "menh-de-quan-he", "q": "------- prepares the patient's medical records is required to maintain confidentiality.", "choices": ["Whoever", "Who", "Whose", "What"], "correct": 0, "explain": "Dịch: Bất kỳ ai chuẩn bị hồ sơ bệnh án đều phải giữ bảo mật. — Chỗ trống mở đầu mệnh đề làm chủ ngữ cả câu, không có tiền ngữ → \"Whoever\" (= anyone who).", "src": "ETS 2026 · Test 4 · Câu 117"}, {"t": 4, "n": 138, "topic": "dieu-kien", "title": "Notice", "passage": "Connelly's Parking Garage\n\nParking is $10 per hour unless you get your parking validated at a participating store. Stores that can validate your parking include Raymond's Department Store, Lola's Fine Dining, Monique's Boutique, and Gretsch Chocolatiers. Just bring your entrance ticket to any of these establishments. [ … ]. You will get your first hour of parking at no charge. {{Q}}, the fee will be $5 per hour.", "q": "Chọn đáp án điền vào chỗ trống (138) trong đoạn văn.", "choices": ["If not", "Then", "In that case", "Nevertheless"], "correct": 1, "explain": "Dịch: Giờ đầu tiên bạn được gửi xe miễn phí. Sau đó, phí là 5 đô mỗi giờ. — \"Then\" (sau đó) nối mốc thời gian tiếp theo. Bẫy: \"If not/In that case\" chỉ dùng khi câu trước nêu một điều kiện.", "src": "ETS 2026 · Test 4 · Câu 138"}, {"t": 4, "n": 103, "topic": "khiem-khuyet", "q": "The real estate agent may ------- a buyer with a neighborhood analysis upon request.", "choices": ["providing", "provide", "provided", "provides"], "correct": 1, "explain": "Dịch: Đại lý bất động sản có thể cung cấp cho người mua bản phân tích khu dân cư khi được yêu cầu. — Sau động từ khiếm khuyết \"may\" dùng V nguyên mẫu → \"provide\".", "src": "ETS 2026 · Test 4 · Câu 103"}, {"t": 1, "n": 122, "topic": "cau-truc-dong-tu", "q": "Marburton residents who wish to ------- a home should contact the award-winning team at Kwan Real Estate.", "choices": ["seller", "sold", "sell", "selling"], "correct": 2, "explain": "Dịch: Cư dân muốn bán nhà nên liên hệ Kwan Real Estate. — \"wish to + V nguyên mẫu\" → \"sell\".", "src": "ETS 2026 · Test 1 · Câu 122"}, {"t": 1, "n": 139, "topic": "cau-truc-dong-tu", "title": "E-mail", "passage": "Dear Ms. Berman,\n\nMy design team is in the process of {{Q}} the plans for your living room. Based on our last conversation, I have chosen different paints for the walls and borders. Please review the attached file and decide whether you like those new colors. If not, it is not too late to make a change. [ … ] Your review will help us refine the design before we start.\n\nPlease let me know if you have any questions. I look forward to hearing from you.", "q": "Chọn đáp án điền vào chỗ trống (139) trong đoạn văn.", "choices": ["finalizing", "finalize", "finalized", "finalizes"], "correct": 0, "explain": "Dịch: Nhóm thiết kế của tôi đang hoàn thiện bản vẽ phòng khách cho bà. — Sau giới từ \"of\" động từ phải ở dạng V-ing: \"in the process of finalizing\".", "src": "ETS 2026 · Test 1 · Câu 139"}, {"t": 2, "n": 106, "topic": "cau-truc-dong-tu", "q": "After reading several reviews, Mr. Kim was able to decide which printer ------- for the office.", "choices": ["buying", "had bought", "buy", "to buy"], "correct": 3, "explain": "Dịch: Sau khi đọc nhiều bài đánh giá, ông Kim quyết định được nên mua máy in nào. — Cấu trúc \"decide which + danh từ + to V\" (từ để hỏi + to V) → \"to buy\".", "src": "ETS 2026 · Test 2 · Câu 106"}, {"t": 2, "n": 133, "topic": "cau-truc-dong-tu", "title": "Advertisement", "passage": "One day nearly 160 years ago, Arianna Sweeney brought some of her homemade muffins to the local town square to give to her friends. Everyone loved them! Before long, Ms. Sweeney started sharing muffins with anyone who wanted one. [ … ]. After a few months, she became known around town as the Muffin Lady.\n\nToday, Muffin Lady Muffins are made by hand {{Q}} the same original recipes developed by Arianna Sweeney. We are committed to baking Muffin Lady Muffins authentically with only the finest ingredients. We hope you enjoy our delicious creations!", "q": "Chọn đáp án điền vào chỗ trống (133) trong đoạn văn.", "choices": ["using", "used", "use", "to use"], "correct": 0, "explain": "Dịch: Ngày nay bánh vẫn được làm thủ công bằng chính công thức gốc. — Câu đã có động từ chính \"are made\"; cụm phân từ chủ động \"using …\" (dùng gì) chỉ cách làm.", "src": "ETS 2026 · Test 2 · Câu 133"}, {"t": 4, "n": 115, "topic": "cau-truc-dong-tu", "q": "The Serenica dining table comes with levelers ------- its stability on uneven surfaces.", "choices": ["ensure", "ensures", "to ensure", "to be ensured"], "correct": 2, "explain": "Dịch: Bàn Serenica đi kèm chân chỉnh cân bằng để bảo đảm vững trên mặt sàn không bằng phẳng. — Câu đã có động từ chính \"comes\"; cần \"to V\" chỉ mục đích → \"to ensure\".", "src": "ETS 2026 · Test 4 · Câu 115"}, {"t": 5, "n": 126, "topic": "cau-truc-dong-tu", "q": "Mr. Sato will call into the meeting ------- the hotel's wireless network.", "choices": ["used", "using", "use", "had used"], "correct": 1, "explain": "Dịch: Ông Sato sẽ gọi vào cuộc họp bằng mạng wifi của khách sạn. — Câu đã có động từ chính; cụm phân từ chủ động \"using …\" (dùng gì) bổ nghĩa cho hành động.", "src": "ETS 2026 · Test 5 · Câu 126"}, {"t": 1, "n": 145, "topic": "lien-tu-part6", "title": "E-mail", "passage": "We have posted a summary of your consultation on our portal. Please take a moment to go through it and let us know if you have any questions.\n\nAs a reminder, you can log in to the portal for various activities. {{Q}}, you can make appointments and payments, view your medical history, review lab results, and request medication refills. [ … ] Rest assured that your personal information is safe and secure.\n\nWe thank you for your business and look forward to serving you again.", "q": "Chọn đáp án điền vào chỗ trống (145) trong đoạn văn.", "choices": ["To repeat", "For instance", "Otherwise", "Consequently"], "correct": 1, "explain": "Dịch: Bạn có thể đăng nhập cổng thông tin để làm nhiều việc. Ví dụ, bạn có thể đặt lịch, thanh toán, xem bệnh sử… — Câu sau liệt kê các việc cụ thể minh hoạ cho \"various activities\" → \"For instance\".", "src": "ETS 2026 · Test 1 · Câu 145"}, {"t": 2, "n": 144, "topic": "lien-tu-part6", "title": "E-mail", "passage": "I am following up on our recent site visit with recommendations for repairing your business's driveway.\n\nAs noted during the visit, the current driveway contains several low spots where water collects during heavy rains. We could address this drainage issue in several ways. The first would be to patch the low spots with filler. {{Q}}, we could remove all of the old asphalt and replace it with a porous material such as crushed gravel. [ … ]. A gravel bed allows rainwater to pass into the underlying soil and be reabsorbed.\n\nPlease give me a call whenever it is convenient so that we can talk about next steps.", "q": "Chọn đáp án điền vào chỗ trống (144) trong đoạn văn.", "choices": ["Likewise", "Therefore", "Regardless", "Alternatively"], "correct": 3, "explain": "Dịch: Cách thứ nhất là trám các chỗ trũng. Hoặc, chúng tôi có thể bóc toàn bộ lớp nhựa đường cũ. — Câu sau đưa ra phương án thay thế cho cách thứ nhất → \"Alternatively\".", "src": "ETS 2026 · Test 2 · Câu 144"}, {"t": 3, "n": 133, "topic": "lien-tu-part6", "title": "Bank advertisement", "passage": "Take advantage of double rewards for a limited time!\n\nStretch your holiday season's shopping spree into January, and we will reward you with $4 cash back on every purchase of $50 or more. Additionally, cashback rewards will be automatically deposited into a separate Avanti savings account and earn a 3% annual interest rate. Enroll in our double-rewards program on Avanti's mobile or desktop app. {{Q}}, stop by an Avanti branch for assistance. [ … ]. On February 1, cashback rewards will return to $2 per $50 transaction.", "q": "Chọn đáp án điền vào chỗ trống (133) trong đoạn văn.", "choices": ["Alternatively", "Likewise", "Nevertheless", "Frequently"], "correct": 0, "explain": "Dịch: Đăng ký chương trình trên ứng dụng di động hoặc máy tính của Avanti. Hoặc, ghé chi nhánh Avanti để được hỗ trợ. — Hai cách đăng ký thay thế nhau → \"Alternatively\".", "src": "ETS 2026 · Test 3 · Câu 133"}, {"t": 5, "n": 132, "topic": "lien-tu-part6", "title": "E-mail", "passage": "Dear Team Members,\n\nAs many of you have recently learned, Claudia Hoffman will end her tenure as art director on Monday, December 30. After ten years in this role, she will be taking on a new professional challenge in Paris. {{Q}}, she will join the leadership team at a top advertising agency. Marcos Molina from Spencer Design will become our new art director. [ … ].\n\nI would like to personally thank Ms. Hoffman for her tremendous leadership. She has been a key factor in our agency's success. Please join me in celebrating her achievements at a farewell dinner after work hours on Friday, December 27. The details will be forthcoming.", "q": "Chọn đáp án điền vào chỗ trống (132) trong đoạn văn.", "choices": ["There", "Instead", "Otherwise", "Afterward"], "correct": 0, "explain": "Dịch: Bà ấy sẽ nhận một thử thách nghề nghiệp mới ở Paris. Ở đó, bà sẽ gia nhập ban lãnh đạo một công ty quảng cáo hàng đầu. — \"There\" (ở đó) thay cho \"in Paris\" ở câu trước, nối hai câu bằng nơi chốn. Instead/Otherwise sai logic; Afterward nói về thời gian sau đó nhưng câu trước đã nói \"sẽ\" rồi nên không cần.", "src": "ETS 2026 · Test 5 · Câu 132"}, {"t": 1, "n": 120, "topic": "tu-han-dinh", "q": "Mr. Ellis and Ms. Barnes were both highly qualified, but ------- got the job.", "choices": ["myself", "neither", "anybody", "whoever"], "correct": 1, "explain": "Dịch: Ông Ellis và bà Barnes đều rất giỏi, nhưng không ai trong hai người được nhận. — Nói về hai người, phủ định → \"neither\".", "src": "ETS 2026 · Test 1 · Câu 120"}, {"t": 2, "n": 143, "topic": "tu-han-dinh", "title": "E-mail", "passage": "I am following up on our recent site visit with recommendations for repairing your business's driveway.\n\nAs noted during the visit, the current driveway contains several low spots where water collects during heavy rains. We could address this drainage issue in {{Q}} ways. The first would be to patch the low spots with filler. Alternatively, we could remove all of the old asphalt and replace it with a porous material such as crushed gravel. [ … ]. A gravel bed allows rainwater to pass into the underlying soil and be reabsorbed.\n\nPlease give me a call whenever it is convenient so that we can talk about next steps.", "q": "Chọn đáp án điền vào chỗ trống (143) trong đoạn văn.", "choices": ["any", "several", "much", "enough"], "correct": 1, "explain": "Dịch: Chúng tôi có thể xử lý vấn đề thoát nước theo vài cách. — \"ways\" là danh từ đếm được số nhiều; câu sau liệt kê cách thứ nhất và một cách khác → \"several\". \"much\" chỉ đi với danh từ không đếm được.", "src": "ETS 2026 · Test 2 · Câu 143"}, {"t": 4, "n": 108, "topic": "tu-han-dinh", "q": "Ten board members plan to attend, which is just ------- to approve the proposal.", "choices": ["enough", "several", "most", "those"], "correct": 0, "explain": "Dịch: Mười thành viên dự định có mặt, vừa đủ để thông qua đề xuất. — \"just enough to + V\" (vừa đủ để).", "src": "ETS 2026 · Test 4 · Câu 108"}, {"t": 4, "n": 111, "topic": "tu-han-dinh", "q": "Graber hair and nail growth supplements come in ------- pill and liquid form.", "choices": ["these", "both", "almost", "likely"], "correct": 1, "explain": "Dịch: Thực phẩm bổ sung Graber có cả dạng viên và dạng nước. — Cặp liên từ \"both … and\".", "src": "ETS 2026 · Test 4 · Câu 111"}, {"t": 4, "n": 136, "topic": "tu-han-dinh", "title": "Notice", "passage": "Connelly's Parking Garage\n\nParking is $10 per hour unless you get your parking validated at a participating store. Stores that can validate your parking include Raymond's Department Store, Lola's Fine Dining, Monique's Boutique, and Gretsch Chocolatiers. Just bring your entrance ticket to {{Q}} of these establishments. [ … ]. You will get your first hour of parking at no charge. Then, the fee will be $5 per hour.", "q": "Chọn đáp án điền vào chỗ trống (136) trong đoạn văn.", "choices": ["any", "all", "each", "either"], "correct": 0, "explain": "Dịch: Chỉ cần mang vé vào cổng tới bất kỳ cửa hàng nào trong số này. — Có 4 cửa hàng, khách chọn một tuỳ ý → \"any of these\". \"either\" chỉ dùng cho hai; \"each/all\" sai nghĩa (không phải mang tới tất cả).", "src": "ETS 2026 · Test 4 · Câu 136"}, {"t": 1, "n": 106, "topic": "trang-tu-danh-tu-ghep", "q": "The hiring manager ------- considered each applicant's résumé and qualifications.", "choices": ["caring", "careful", "carefully", "carefulness"], "correct": 2, "explain": "Dịch: Quản lý tuyển dụng đã cân nhắc kỹ hồ sơ và năng lực từng ứng viên. — Vị trí giữa chủ ngữ và động từ chính \"considered\" → trạng từ \"carefully\".", "src": "ETS 2026 · Test 1 · Câu 106"}, {"t": 1, "n": 108, "topic": "trang-tu-danh-tu-ghep", "q": "Tarateer Pharmaceuticals is varying its product ------- to include over-the-counter medications.", "choices": ["to line", "lining", "lined", "line"], "correct": 3, "explain": "Dịch: Tarateer đang đa dạng hoá dòng sản phẩm để có thêm thuốc không kê đơn. — Danh từ ghép \"product line\" (dòng sản phẩm): sau \"its product\" cần danh từ \"line\".", "src": "ETS 2026 · Test 1 · Câu 108"}, {"t": 2, "n": 126, "topic": "trang-tu-danh-tu-ghep", "q": "Several Seoul-based companies have ------- redesigned their workplaces to be more colorful and comfortable.", "choices": ["note", "noted", "notable", "notably"], "correct": 3, "explain": "Dịch: Nhiều công ty ở Seoul đã thiết kế lại nơi làm việc một cách đáng chú ý. — Chen giữa \"have\" và V3 \"redesigned\" → trạng từ \"notably\".", "src": "ETS 2026 · Test 2 · Câu 126"}, {"t": 3, "n": 107, "topic": "trang-tu-danh-tu-ghep", "q": "The heavy traffic on the way to the airport ------- caused Ms. Ikeda to miss her flight.", "choices": ["nearly", "near", "nears", "nearness"], "correct": 0, "explain": "Dịch: Kẹt xe trên đường ra sân bay suýt khiến cô Ikeda lỡ chuyến bay. — Giữa chủ ngữ và động từ \"caused\" → trạng từ \"nearly\" (suýt). \"near\" là tính từ/giới từ.", "src": "ETS 2026 · Test 3 · Câu 107"}, {"t": 3, "n": 117, "topic": "trang-tu-danh-tu-ghep", "q": "Our new app is ------- designed to provide data-driven insights to investment professionals.", "choices": ["specify", "specific", "specificity", "specifically"], "correct": 3, "explain": "Dịch: Ứng dụng mới được thiết kế riêng để cung cấp phân tích dựa trên dữ liệu. — Giữa \"is\" và V3 \"designed\" → trạng từ \"specifically\".", "src": "ETS 2026 · Test 3 · Câu 117"}, {"t": 4, "n": 113, "topic": "trang-tu-danh-tu-ghep", "q": "Mr. Olivero praised the film in his review, even though he ------- disliked its aesthetic style.", "choices": ["personal", "personally", "personals", "person"], "correct": 1, "explain": "Dịch: Ông Olivero khen bộ phim dù cá nhân ông không thích phong cách thẩm mỹ của nó. — Giữa chủ ngữ \"he\" và động từ \"disliked\" → trạng từ \"personally\".", "src": "ETS 2026 · Test 4 · Câu 113"}, {"t": 5, "n": 102, "topic": "trang-tu-danh-tu-ghep", "q": "The first 150 visitors to the new fitness park will each receive a complimentary water -------.", "choices": ["bottle", "bottled", "bottling", "to bottle"], "correct": 0, "explain": "Dịch: 150 khách đầu tiên sẽ được tặng một chai nước. — Danh từ ghép \"water bottle\": sau \"a complimentary water\" cần danh từ \"bottle\".", "src": "ETS 2026 · Test 5 · Câu 102"}];
